import { z } from 'zod';
import type { Pool } from 'pg';

export const GpsCheckinSchema = z.object({
  employeeId: z.string().uuid(),
  branchId: z.string().uuid(),
  lat: z.number().min(-90).max(90),
  lng: z.number().min(-180).max(180),
  deviceFingerprint: z.string().min(16),
});

export function haversineMeters(lat1: number, lng1: number, lat2: number, lng2: number): number {
  const R = 6371000;
  const toRad = (deg: number) => (deg * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

export async function approvePurchaseOrderAtomic(
  pool: Pool,
  tenantId: string,
  poId: string,
  approverId: string,
) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query("SELECT set_config('app.current_tenant_id', $1, true)", [tenantId]);

    // Khoa dong PO va kiem tra han muc phe duyet da cap ngay trong Postgres
    const poRes = await client.query(
      `SELECT id, amount_vnd, current_level, status, department_id
       FROM erp_purchase_orders
       WHERE id = $1 AND tenant_id = $2 FOR UPDATE`,
      [poId, tenantId],
    );
    const po = poRes.rows[0];
    if (!po || po.status !== 'PENDING_APPROVAL') {
      throw new Error('PO khong ton tai hoac da xu ly xong');
    }

    const nextStatus = po.amount_vnd > 50_000_000 && po.current_level < 2
      ? 'PENDING_APPROVAL'
      : 'APPROVED_READY_MISA';

    await client.query(
      `UPDATE erp_purchase_orders
       SET current_level = current_level + 1, status = $2, approved_by = $3, updated_at = now()
       WHERE id = $1`,
      [poId, nextStatus, approverId],
    );
    await client.query('COMMIT');
    return { poId, nextStatus };
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}
